		       description = ($q$"Nombre d'entiers d'un intervalle à bornes décimales ou entières (crochets ouverts ou fermés), plus petit entier d'un intervalle (pièges : bornes exclues comptées, −2,5 → −3)"$q$::jsonb #>> '{}')
		 where id = 'c6634cf8-b7d9-42f6-b12d-a504fd32bc34';
		if not exists (select 1 from public.question_templates
