		                  and variations = $q$[{"statement":"Combien de nombres **entiers** l'intervalle $\\left[{{eval:(10*la+fa)/10;d}}\\,;{{eval:(10*lb+fb)/10;d}}\\right]$ contient-il ?\n\n$?$ entiers","variables":[{"name":"la","expression":"-9..4"},{"name":"w","expression":"2..8"},{"name":"lb","expression":"eval:la+w"},{"name":"fa","expression":"1..9"},{"name":"fb","expression":"1..9"},{"name":"m","expression":"eval:la+1"},{"name":"M","expression":"eval:lb"}],"blanks":[{"expectedAnswer":"{{eval:w}}","expectedErrors":[{"answer":"{{eval:w+1}}","message":"Tu as compté un entier qui n'est pas dans l'intervalle : vérifie quel est le premier entier après la borne de gauche.","label":"Entier avant la borne de gauche compté"},{"answer":"{{eval:w-1}}","message":"Tu as fait la différence des entiers extrêmes : elle compte les écarts entre eux, pas les entiers eux-mêmes.","label":"Oubli du « + 1 » (différence des entiers extrêmes)"},{"answer":"{{eval:w+2}}","message":"Tu as compté des entiers en dehors de l'intervalle : les bornes ne sont pas entières, les entiers extrêmes sont à l'intérieur.","label":"Bornes arrondies vers l'extérieur"}]}],"correction":{"steps":["Les bornes ne sont pas entières. Le plus petit entier de l'intervalle est ${{eval:la+1}}$ (le premier entier **après** ${{eval:(10*la+fa)/10;d}}$), le plus grand est ${{eval:lb}}$.","On compte les entiers de ${{eval:la+1}}$ à ${{eval:lb}}$ : {{if:m<0|${{eval:M}}-({{eval:m}})+1=\\textcolor{{{color:primary.0}}}{{{eval:M-(m)+1}}}$|${{eval:M}}-{{eval:m}}+1=\\textcolor{{{color:primary.0}}}{{{eval:M-(m)+1}}}$}}."]},"hint":"Cherche le plus petit et le plus grand entier de l'intervalle, puis compte les entiers de l'un à l'autre. Attention : la différence de deux entiers ne donne pas le nombre d'entiers."},{"statement":"Combien de nombres **entiers** l'intervalle $\\left{{if:o1==0|[|]}}{{a}}\\,;{{b}}\\right{{if:o2==0|]|[}}$ contient-il ?\n\n$?$ entiers","variables":[{"name":"a","expression":"-9..5"},{"name":"w","expression":"2..9"},{"name":"b","expression":"eval:a+w"},{"name":"o1","expression":"0|1"},{"name":"o2","expression":"0|1"},{"name":"m","expression":"eval:a+o1"},{"name":"M","expression":"eval:b-o2"}],"blanks":[{"expectedAnswer":"{{eval:w+1-o1-o2}}","expectedErrors":[{"answer":"{{eval:w+1}}","message":"Tu as compté une borne alors que le crochet est ouvert de ce côté : elle n'est pas dans l'intervalle.","label":"Borne exclue comptée"},{"answer":"{{eval:w-o1-o2}}","message":"Tu as fait la différence des entiers extrêmes : elle compte les écarts entre eux, pas les entiers eux-mêmes.","label":"Oubli du « + 1 » (différence des entiers extrêmes)"},{"answer":"{{eval:w-1+o1+o2}}","message":"Tu as confondu crochet ouvert et crochet fermé : un crochet tourné vers l'extérieur exclut la borne.","label":"Crochets ouverts et fermés confondus"}]}],"correction":{"steps":["{{if:o1==0|Le crochet est **fermé** en ${{a}}$ : ${{a}}$ est dans l'intervalle.|Le crochet est **ouvert** en ${{a}}$ : ${{a}}$ n'est **pas** dans l'intervalle.}} {{if:o2==0|Le crochet est **fermé** en ${{b}}$ : ${{b}}$ est dans l'intervalle.|Le crochet est **ouvert** en ${{b}}$ : ${{b}}$ n'est **pas** dans l'intervalle.}}","Les entiers vont de ${{eval:m}}$ à ${{eval:M}}$ : {{if:m<0|${{eval:M}}-({{eval:m}})+1=\\textcolor{{{color:primary.0}}}{{{eval:M-(m)+1}}}$|${{eval:M}}-{{eval:m}}+1=\\textcolor{{{color:primary.0}}}{{{eval:M-(m)+1}}}$}}."]},"hintFromFirstStep":true},{"statement":"Quel est le **plus petit** nombre entier de l'intervalle $\\left{{if:o1==0|[|]}}{{a}}\\,;{{b}}\\right]$ ?\n\n$?$","variables":[{"name":"a","expression":"-9..5"},{"name":"w","expression":"2..9"},{"name":"b","expression":"eval:a+w"},{"name":"o1","expression":"0|1"}],"blanks":[{"expectedAnswer":"{{eval:a+o1}}","expectedErrors":[{"answer":"{{eval:a+1-o1}}","message":"Tu as mal lu le crochet de gauche : regarde s'il contient la borne ${{a}}$ ou s'il l'exclut.","label":"Crochet de gauche mal lu"},{"answer":"{{b}}","message":"Tu as donné le plus grand entier de l'intervalle : on cherche le plus petit.","label":"Plus grand entier au lieu du plus petit"},{"answer":"{{eval:a-1}}","message":"Ce nombre est avant la borne de gauche : il n'est pas dans l'intervalle.","label":"Entier pris avant la borne de gauche"}]}],"correction":{"steps":["{{if:o1==0|Le crochet est **fermé** en ${{a}}$ : ${{a}}$ est dans l'intervalle, c'est son plus petit entier : $\\textcolor{{{color:primary.0}}}{{{a}}}$.|Le crochet est **ouvert** en ${{a}}$ : ${{a}}$ n'est **pas** dans l'intervalle. Le plus petit entier est le suivant : $\\textcolor{{{color:primary.0}}}{{{eval:a+1}}}$.}}"]},"hint":"Regarde le crochet de gauche : est-il tourné vers ${{a}}$ (borne comprise) ou vers l'extérieur (borne exclue) ?"},{"statement":"Quel est le **plus petit** nombre entier de l'intervalle $\\left[{{eval:(10*la+fa)/10;d}}\\,;{{eval:(10*lb+fb)/10;d}}\\right]$ ?\n\n$?$","variables":[{"name":"la","expression":"-9..-1"},{"name":"w","expression":"2..8"},{"name":"lb","expression":"eval:la+w"},{"name":"fa","expression":"1..9"},{"name":"fb","expression":"1..9"}],"blanks":[{"expectedAnswer":"{{eval:la+1}}","expectedErrors":[{"answer":"{{la}}","message":"Ce nombre est plus petit que la borne de gauche : il n'est pas dans l'intervalle.","label":"Entier avant la borne négative (−2,5 → −3)"},{"answer":"{{lb}}","message":"Tu as donné le plus grand entier de l'intervalle : on cherche le plus petit.","label":"Plus grand entier au lieu du plus petit"},{"answer":"{{eval:(10*la+fa)/10;d}}","message":"Tu as donné la borne de gauche, mais elle n'est pas un nombre entier.","label":"Borne décimale donnée au lieu d'un entier"}]}],"correction":{"steps":["Sur la droite graduée, ${{eval:(10*la+fa)/10;d}}$ est entre ${{eval:la}}$ et ${{eval:la+1}}$.","Les nombres de l'intervalle sont **après** ${{eval:(10*la+fa)/10;d}}$ : le plus petit entier est $\\textcolor{{{color:primary.0}}}{{{eval:la+1}}}$ (et non ${{eval:la}}$, qui est plus petit que ${{eval:(10*la+fa)/10;d}}$)."]},"hint":"Place ${{eval:(10*la+fa)/10;d}}$ sur une droite graduée : entre quels entiers se trouve-t-il ? Les nombres de l'intervalle sont à sa droite."},{"statement":"Écris l'ensemble des nombres **entiers** de l'intervalle $\\left[{{eval:(10*la+fa)/10;d}}\\,;{{eval:(10*lb+fb)/10;d}}\\right]$.\n\nÉcris-les entre accolades, séparés par des points-virgules.\n\n$?$","variables":[{"name":"la","expression":"-6..-1"},{"name":"w","expression":"3|4"},{"name":"lb","expression":"eval:la+w"},{"name":"fa","expression":"1..9"},{"name":"fb","expression":"1..9"}],"blanks":[{"answerKind":"intervalles","expectedAnswer":"\\{ {{eval:la+1}} ; {{eval:la+2}} ; {{eval:la+3}}{{if:w==4| ; {{eval:la+4}}|}} \\}","expectedErrors":[{"answer":"\\{ {{la}} ; {{eval:la+1}} ; {{eval:la+2}} ; {{eval:la+3}}{{if:w==4| ; {{eval:la+4}}|}} \\}","message":"Tu as mis ${{la}}$, qui est plus petit que la borne de gauche : il n'est pas dans l'intervalle.","label":"Entier avant la borne négative (−2,5 → −3)"},{"answer":"\\{ {{eval:la+1}} ; {{eval:la+2}} ; {{eval:la+3}}{{if:w==4| ; {{eval:la+4}}|}} ; {{eval:lb+1}} \\}","message":"Tu as mis ${{eval:lb+1}}$, qui est plus grand que la borne de droite : il n'est pas dans l'intervalle.","label":"Entier après la borne de droite"},{"answer":"[{{eval:la+1}};{{lb}}]","message":"Tu as écrit un intervalle : il contient aussi tous les nombres non entiers. Écris la liste des entiers entre accolades.","label":"Intervalle au lieu de l'ensemble des entiers"}]}],"correction":{"steps":["Sur la droite graduée, ${{eval:(10*la+fa)/10;d}}$ est entre ${{la}}$ et ${{eval:la+1}}$, et ${{eval:(10*lb+fb)/10;d}}$ est entre ${{lb}}$ et ${{eval:lb+1}}$.","Les entiers de l'intervalle vont de ${{eval:la+1}}$ (et non ${{la}}$, plus petit que ${{eval:(10*la+fa)/10;d}}$) à ${{lb}}$ : $\\textcolor{{{color:primary.0}}}{\\{ {{eval:la+1}} ; {{eval:la+2}} ; {{eval:la+3}}{{if:w==4| ; {{eval:la+4}}|}} \\}}$."]},"hint":"Cherche le premier entier après la borne de gauche (attention, elle est négative), puis écris tous les entiers